def test_multiple_hooks(self):

    def add_foo_header(args):
        if not args.get('headers'):
            args['headers'] = {}

        args['headers'].update({
            'X-Foo': 'foo'
        })

        return args

    def add_bar_header(args):
        if not args.get('headers'):
            args['headers'] = {}

        args['headers'].update({
            'X-Bar': 'bar'
        })

        return args

    for service in SERVICES:
        url = service('headers')

        response = get(url=url,
            hooks={
                'args': [add_foo_header, add_bar_header]
            }
        )

        assert 'foo' in response.text
        assert 'bar' in response.text

def validate_client_key(self, client_key):
    """Validates that supplied client key is a registered and valid client.

    Note that if the dummy client is supplied it should validate in same
    or nearly the same amount of time as a valid one.

    Bad:

        if client_key == self.dummy_client:
            return False
        else:
            return storage.has_client(client_key)

    Good:

        return storage.has_client(client_key) and client_key != self.dummy_client
    """
    raise NotImplementedError("Subclasses must implement this function.")

